let preschoolCategory='Todos',preschoolAge='2–3 anos',preschoolSelected=0;
function renderInitiation(){const l=preschoolLessons[preschoolSelected],young=preschoolAge==='2–3 anos';return `<div class="page-intro"><div><span class="eyebrow">INICIAÇÃO MUSICAL · 2 A 5 ANOS</span><h1>Pequenos ouvidos, grandes descobertas.</h1><p class="lead">50 propostas lúdicas em cinco temas. Escolha pela resposta da turma, com repetição, acolhimento e liberdade de observar antes de participar.</p></div></div><div class="toolbar"><label>Tema <select id="preschoolCategory">${['Todos',...new Set(preschoolLessons.map(x=>x.category))].map(a=>`<option ${a===preschoolCategory?'selected':''}>${a}</option>`).join('')}</select></label></div><div class="lesson-grid">${preschoolLessons.map((x,i)=>preschoolCategory==='Todos'||x.category===preschoolCategory?`<button class="lesson-card ${i===preschoolSelected?'selected':''}" data-preschool="${i}"><span class="lesson-icon" style="--tint:#fff0d8">${x.icon}</span><span><span class="tiny">${x.category}</span><h3>${x.title}</h3><p>${x.goal}</p></span></button>`:'').join('')}</div><section class="panel" id="preschoolPlan"><span class="eyebrow">${preschoolAge} · ${young?'20':'30'} MINUTOS SUGERIDOS</span><h2>${l.icon} ${l.title}</h2><div class="goal"><strong>Objetivo</strong>${l.goal}</div><h3>História participativa · roteiro para contar</h3><p class="note">História autoral do Musiverso. Leia com naturalidade, pause e incorpore as respostas reais das crianças. As cenas fazem parte do tempo de contar, brincar e inventar previsto abaixo.</p>${l.scenes.map((scene,i)=>`<article class="story-scene"><span class="eyebrow">CENA ${i+1}</span><h3>${scene.title}</h3><p class="story-speech">${scene.say}</p><div class="story-invite"><strong>Convite à participação</strong><p>${scene.invite}</p></div><p class="note"><strong>Condução do professor:</strong> ${scene.action}</p></article>`).join('')}<details class="goal"><summary><strong>Desdobrar a mesma história em outras linguagens</strong></summary><p><b>Artes visuais:</b> ${l.arts}</p><p><b>Movimento:</b> ${l.movement}</p><p><b>Objeto:</b> ${l.object}</p><p><b>Brincadeira:</b> ${l.game}</p><p><b>Instrumento:</b> ${l.instrument}</p><p class="note">Escolha um ou dois desdobramentos para este encontro; os demais podem ser retomados em outra aula. Referência de planejamento integrado: HADOBI, de Estêvão Marques. Estes textos e propostas são autorais, não reproduzem seu material didático.</p></details><ol class="steps"><li><span class="step-num">1</span><div><h3>Chegar e acolher</h3><p>Cante uma saudação curta com os nomes. Ofereça participação por olhar, gesto ou voz.</p></div><span class="time">${young?3:5} min</span></li><li><span class="step-num">2</span><div><h3>Contar e escutar</h3><p>Conte a história acima com pausas e dois sons contrastantes. Convide sem exigir imitação.</p></div><span class="time">${young?4:5} min</span></li><li><span class="step-num">3</span><div><h3>Brincar com o som</h3><p>${l.practice}</p></div><span class="time">${young?6:8} min</span></li><li><span class="step-num">4</span><div><h3>Inventar juntos</h3><p>${young?'Repita a brincadeira com um elemento por vez. Deixe a criança escolher entre dois sons ou gestos.':'Convide duplas a inventar uma sequência de dois ou três elementos, com alternância de papéis.'}</p></div><span class="time">${young?4:7} min</span></li><li><span class="step-num">5</span><div><h3>Despedir e observar</h3><p>Retome o som preferido e cante a despedida. Registre se a criança orientou a atenção ao som, experimentou, imitou ou criou, sem notas nem comparação.</p></div><span class="time">${young?3:5} min</span></li></ol><div class="sub-grid" style="margin-top:20px"><div><h3>Preparar o espaço</h3><p>Use imagens grandes e instrumentos infantis adequados à idade, íntegros e supervisionados. Evite peças pequenas, recipientes que possam abrir e sons próximos aos ouvidos. Não compartilhar bocais.</p></div><div><h3>Adaptar a participação</h3><p>Ofereça movimento sentado, gestos com mãos ou olhar. Reduza volume, número de sons e duração conforme a resposta da criança. A criança pode observar antes de participar.</p></div></div><div class="goal"><strong>Orff e Dalcroze como inspiração</strong>Fala, canto e exploração corporal podem conduzir a criação. Na escuta em movimento, o professor adapta a música ao grupo. Priorize a experiência sonora antes de nomes de figuras ou leitura de pauta.</div><p class="note">No app: o professor pode mostrar brevemente uma imagem ou um timbre relacionado ao tema. As brincadeiras acontecem principalmente em interação presencial; sons de animais podem ser feitos pela voz do professor.</p><div class="actions"><button class="btn" id="printPreschool">⎙ Imprimir esta proposta</button></div></section>`}
document.addEventListener('change',e=>{if(e.target.id==='preschoolAge'){preschoolAge=e.target.value;render()}if(e.target.id==='preschoolCategory'){preschoolCategory=e.target.value;preschoolSelected=preschoolLessons.findIndex(l=>preschoolCategory==='Todos'||l.category===preschoolCategory);render()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.preschool!==undefined){preschoolSelected=Number(b.dataset.preschool);render();document.querySelector('#preschoolPlan').scrollIntoView({behavior:'smooth'})}if(b.id==='printPreschool'){const l=preschoolLessons[preschoolSelected];document.querySelector('#printSheet').innerHTML='<div class="sheet-header"><strong>MUSIVERSO KIDS · INICIAÇÃO</strong><span>'+preschoolAge+'</span></div>'+document.querySelector('#preschoolPlan').innerHTML.replace(/<div class="actions">[\s\S]*?<\/div>/,'');window.print()}});
